values ('dialog_fq_star_001', 'fq_star_001', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "Legionnaire. The Purification Begins — Grand Justiciar Aurelius speaks with the gravity of a man who has watched h...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "A Place in the Sand: First Watch 01. In Dune Outskirts: Defeat 3 DUNE_SCAVENGER. Complete the task as assigned and report who stood beside you when the line held.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 725)
