values ('dialog_fq_star_079', 'fq_star_079', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "The code demands action. Legion duty.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Canyon Claim: Terms of Passage 04. In Eternal Gate: Defeat 1 ASHEN_DRAKE. Complete the task as assigned and report who stood beside you when the line held.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 803)
