values ('dialog_msq_lv40_master_reminder', 'msq_lv40_master_reminder', 'npc_class_advisor', 'start', '[{"id": "start", "text": "The Ascension", "options": [{"text": "Accept Quest", "next": "confirm_accept", "action": ""}, {"text": "Details...", "next": "details", "action": ""}, {"text": "Not right now.", "next": "exit", "action": "exit"}]}, {"id": "details", "text": "Objectives:\n• Speak with class_trainer\n\nRewards: 8000 EXP · 2000 currency · 1000 CRD", "options": [{"text": "Accept Quest", "next": "confirm_accept", "action": ""}, {"text": "Go back.", "next": "start", "action": ""}]}, {"id": "confirm_accept", "text": "Confirm that you are ready to take this assignment.", "options": [{"text": "Confirm acceptance", "next": "exit", "action": "accept_quest"}, {"text": "Return to the briefing", "next": "start", "action": ""}]}]'::jsonb, 'dialog_quests.json', 827)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_unlisted_two_chairs', 'mq_unlisted_two_chairs', 'npc_mystery_edda_fen', 'greeting', '[{"id": "greeting", "text": "The chair isn''t abandoned. Someone fixed its leg yesterday. My register says nobody lives here. Help me find which record is lying.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The small chair has fresh binding; the large one has weathered dust. A torn census slip retains an occupancy mark but loses its address line. The doorplate carries a household number, not a military unit number.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A repaired chair stands outside a household listed as empty. Edda wants a name restored without revealing where the family now sleeps.", "options": [{"text": "Restore the name, withhold the address", "next": "choice_1", "action": ""}, {"text": "Share a sealed address with relief workers", "next": "choice_2", "action": ""}, {"text": "Let the family authorize the correction", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The public index gains a name without a location. The cost is clear: Aid workers need Edda as an intermediary.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A confidential aid entry accompanies the corrected name. The cost is clear: The family must trust a restricted channel.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Edda leaves an unsigned entry for its owner to approve. The cost is clear: Recognition waits for consent.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Carbon Census Slip from Malfunctioning Ward Indexer in The Unlisted Ward. Examine Repaired Doorplate and compare its evidence. Examine Census Cabinet and compare its evidence. Discuss your finding with Edda Fen in The Unlisted Ward.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 828)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_unlisted_second_number', 'mq_unlisted_second_number', 'npc_mystery_edda_fen', 'greeting', '[{"id": "greeting", "text": "I can make both columns agree by throwing one away. That would be neat. It would also be wrong.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The lower numeral is cut into stone; the upper numeral is painted. The lower series skips occupied doors but follows conduit junctions. The cabinet labels the two columns district and household.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "Two surveys disagree about the same doorway. The older mark describes a utility district, while the newer mark counts households.", "options": [{"text": "Publish both systems with a legend", "next": "choice_1", "action": ""}, {"text": "Prioritize the household number", "next": "choice_2", "action": ""}, {"text": "Prioritize the utility number", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: Both numbering schemes remain visible. The cost is clear: Readers must learn a harder index.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Residents gain a readable primary label. The cost is clear: Maintenance crews need an extra lookup.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Repair crews recover the older route. The cost is clear: Civil claims need an attached note.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Repaired Doorplate and compare its evidence. Examine Census Cabinet and compare its evidence. Discuss your finding with Edda Fen in The Unlisted Ward.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 829)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_unlisted_obedient_lock', 'mq_unlisted_obedient_lock', 'npc_mystery_edda_fen', 'greeting', '[{"id": "greeting", "text": "It follows the register exactly. That''s the problem. Stop it without calling the people behind that door intruders.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The automaton''s authorization plate names a municipal service. Its rejection stamp predates the relocation notice. Its patrol follows the same blocked doorway, never the occupied side lanes.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The Ward Indexer repeatedly bars a relief passage because its stale register has no authorized households.", "options": [{"text": "Submit the fault to municipal repair", "next": "choice_1", "action": ""}, {"text": "Mark a community-managed passage", "next": "choice_2", "action": ""}, {"text": "Keep the old index as evidence", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The obstruction is recorded as a service failure. The cost is clear: Formal repair takes time.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A local maintenance notice replaces the rejection stamp. The cost is clear: Residents bear responsibility for access.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Edda retains a copy before a technician repairs it. The cost is clear: Storage and custody cost effort.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Stop the dangerous Malfunctioning Ward Indexer in The Unlisted Ward. Inspect the now-safe evidence area in The Unlisted Ward. Examine Repaired Doorplate and compare its evidence. Examine Census Cabinet and compare its evidence. Discuss your finding with Edda Fen in The Unlisted Ward.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 830)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_unlisted_folded_route', 'mq_unlisted_folded_route', 'npc_mystery_edda_fen', 'greeting', '[{"id": "greeting", "text": "The fold kept this dry. It also kept it private. Don''t mistake finding a route for owning the people at its end.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The exterior bears a public household mark. The interior names a relief transfer, not a military movement. The notice says restricted delivery, with no claim of faction disloyalty.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A relocation notice hides a relief route inside its fold. Publishing it would help aid crews and expose people who chose anonymity.", "options": [{"text": "Copy destinations only to relief staff", "next": "choice_1", "action": ""}, {"text": "Publish quantities without destinations", "next": "choice_2", "action": ""}, {"text": "Return the notice to its household", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: A restricted relief list is prepared. The cost is clear: Aid depends on a trusted custodian.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A public needs report excludes identifying details. The cost is clear: Delivery requires another channel.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The record owner decides what may circulate. The cost is clear: Verification stays local.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Folded Relocation Notice from Malfunctioning Ward Indexer in The Unlisted Ward. Examine Repaired Doorplate and compare its evidence. Examine Census Cabinet and compare its evidence. Discuss your finding with Edda Fen in The Unlisted Ward.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 831)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_unlisted_right_to_remain', 'mq_unlisted_right_to_remain', 'npc_mystery_edda_fen', 'greeting', '[{"id": "greeting", "text": "I wanted to fill every blank. Now I know some blanks are chosen. Help me write a register that can tell the difference.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The doorplate proves occupation, not identity. The two numbering systems serve different public needs. The folded route shows that privacy and assistance can coexist.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The ward can be recognized without every resident being named. Edda asks how to preserve that distinction for the next census.", "options": [{"text": "Create an anonymous occupied category", "next": "choice_1", "action": ""}, {"text": "Keep a sealed identity supplement", "next": "choice_2", "action": ""}, {"text": "Require renewed household consent", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The ward is recorded without listing every person. The cost is clear: Named claims still require witnesses.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Public and restricted records are separated. The cost is clear: Trust rests with its custodians.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Residents retain a recurring say in their entry. The cost is clear: Records become slower to update.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Repaired Doorplate and compare its evidence. Examine Census Cabinet and compare its evidence. Discuss your finding with Edda Fen in The Unlisted Ward.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 832)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
