values ('dialog_mq_muster_warning_not_oath', 'mq_muster_warning_not_oath', 'npc_mystery_tovan_rell', 'greeting', '[{"id": "greeting", "text": "A monument rings when someone important visits. A warning rings when someone ordinary is in danger. Which job are we paying for?", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The fourth beat has a specific safety meaning. The absent crew obeyed it. The wrecker fault explains why the warning failed.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The repaired bell can become a ceremonial monument or a working civilian warning. Tovan cannot maintain both roles without help.", "options": [{"text": "Keep it a working warning bell", "next": "choice_1", "action": ""}, {"text": "Move the original into a memorial", "next": "choice_2", "action": ""}, {"text": "Give maintenance to a joint work council", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The yard retains its evacuation signal. The cost is clear: A crew must fund regular checks.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The original becomes evidence beside a working copy. The cost is clear: A replacement must carry the warning.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The bell gains shared civilian custodians. The cost is clear: Rival crews must keep cooperating.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Split Muster Bell and compare its evidence. Examine Workshop Roll and compare its evidence. Discuss your finding with Tovan Rell in Hollow Muster Yard.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 837)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
