values ('dialog_mq_zero_inside_label', 'mq_zero_inside_label', 'npc_mystery_sella_quinn', 'greeting', '[{"id": "greeting", "text": "Serial''s genuine. Story''s facing the wrong way. Turn your attention, not the number.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The stencil faces the crate interior. The scale log marks outbound packaging as returnable. The repeated serial refers to the container, not two cargo loads.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "An inward stencil makes a returnable container look like a new delivery. Its direction matters more than its serial number.", "options": [{"text": "Correct the delivery count", "next": "choice_1", "action": ""}, {"text": "Flag the stencil for physical inspection", "next": "choice_2", "action": ""}, {"text": "Publish a return-label standard", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The record separates container returns from goods. The cost is clear: The carrier''s volume claim shrinks.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: An inspector confirms direction before settlement. The cost is clear: A shipment waits at the berth.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: A clearer standard prevents the same dispute. The cost is clear: Dock crews must relabel stock.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Zero Berth Scale and compare its evidence. Examine Reversed Shipping Stencil and compare its evidence. Discuss your finding with Sella Quinn in Zero Berth Customs Annex.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 839)
